#!/usr/bin/env bash
# Default label set: does LaB-RAG do better with PadChest-60 labels than CheXbert-14?
# Qwen3.5-27B with the image (518 px). PadChest-60 labels come from the PadChest head
# (experiments/padchest-attn.sh) for targets and corpus alike, so the control is
# CheXbert-14 with predicted corpus labels too (out of fold for the classifier's train
# patients). Next to retrieval-only, image only and CheXbert-14 with reference corpus
# labels (already generated by pilot-image.sh). Both sampling seeds, on the pilot set.
# Peak 2 GPUs.
set -euo pipefail
cd "$(dirname "$0")/.."

s() { slurm/submit.sh --parsable --kill-on-invalid-dep=yes "$@"; }
B="labrag build-prompts --experiment pilot --section findings"
F=pilot/chexpertplus/findings
CLF=attn-nvfp4-seed1
PADCHEST=padchest/raddino.$CLF/padchest60
SET=pilot
P=section-simple-image

oof=$(s --gres=gpu:1 --cpus-per-task=16 --mem=64G -- labrag classify --dataset chexpertplus --section findings --classifier attn --tokens nvfp4 --seed 1 --folds 5)
pre=$(s --gres=gpu:1 --cpus-per-task=16 --mem=64G -- labrag predict --dataset chexpertplus --section findings --classifier $PADCHEST)
p1=$(s -d afterok:$oof -- $B --condition labrag --classifier $CLF-oof5 --corpus-labels predicted --prompt $P)
p2=$(s -d afterok:$pre -- $B --condition labrag --predictions $PADCHEST --prompt $P)
NEW="$F/labrag.$CLF-oof5.chexbert14.u0.corpus-predicted/$P $F/labrag.padchest.$CLF.padchest60/$P"
OLD="$F/retrieval-only/section-naive-image $F/no-context/section-image
  $F/labrag.$CLF.chexbert14.u0/$P"

gens() { for p in $2; do echo -n "$p/$1/$SET "; done; }
ids=""
runs=""
dep=""
for sampling in qwen3.5-thinking-32k qwen3.5-thinking-32k-seed2; do
  run=qwen3.5-27b-vision.$sampling
  g=$(s -d afterok:$p1:$p2 --gres=gpu:1 -- labrag generate --prompts $NEW --set $SET --model qwen3.5-27b-vision --sampling $sampling)
  e=$(s -d afterok:$g --gres=gpu:1 -- labrag evaluate --generations $(gens $run "$NEW"))
  ids+=" $g $e"
  dep+=":$e"
  runs+=" $(gens $run "$NEW $OLD")"
done
cmp=$(s -d afterok$dep -- labrag compare --generations $runs --out $F/qwen3.5-27b.padchest/$SET)
echo "classify $oof predict $pre prompts $p1 $p2 generate/evaluate$ids compare $cmp"
